function gbkToutf(title){
	const {java} = this;
 let URLDecoder = Packages.java.net.URLDecoder;
 let 	gb2312Str = URLDecoder.decode(title,"gbk");
 let utf8Str = URLDecoder.decode(title,"utf-8");
 let result = gb2312Str.length() >= utf8Str.length();
	title = result?decodeURI(title):gb2312Str;
	return title
	}


