html
<js>//保存第一页网站全部代码在html
html='\n'+result


//获取总页数，净化多余的文字
page={{@@.ant-pagination.0@li.-2@text}}


//当页数大于一时，获取当前网址并净化
//也就是将  .html  净化成  _
if(page>1){
url=baseUrl.replace('','')


//打印xxx，用于源校验排版
java.log('第1页加载完成，共'+page+'页\n'+baseUrl)


//for循环，获取元素 i ，i=2-总页数
for(i=2;i<=page;i++){


//循环打印xxx，用于源校验排版
java.log('第'+i+'页加载完成，共'+page+'页\n'+url+'?page='+i+'')


//通过for循环用java.ajax(完整的下一页网址)循环打印所有下一页网站的全部代码，然后拼接到第一页网站代码后面
html+='\n'+java.ajax(url+'?page='+i+'')
 }
}
//在全部网站代码的基础上获取想要的图片
//然后用js保存，主要作用是分隔，方便排版最终正文
</js>
