url=baseUrl.replace('.html','_')


//打印xxx，用于源校验排版
java.log('第1页加载完成，共'+page+'页\n'+baseUrl)


//for循环，获取元素 i ，i=2-总页数
for(i=2;i<=page;i++){


//循环打印xxx，用于源校验排版
java.log('第'+i+'页加载完成，共'+page+'页\n'+url+i+'.html')


//通过for循环用java.ajax(完整的下一页网址)循环打印所有下一页网站的全部代码，然后拼接到第一页网站代码后面
html+='\n'+java.ajax(url+i+'.html')
 }
}
//在全部网站代码的基础上获取想要的图片
