function copy(tar) {
	let data=typeof tar=="string"?tar:tar.innerText;
	navigator.clipboard &&
	navigator.clipboard
	.writeText(data)
	.then(_=>Toast("复制成功"))
	.catch(_=>oldCopy(data)) ||
	oldCopy(data)
}
function oldCopy(str) {
    if (str != "") {
        let input = document.createElement("input");
        input.id = "copy";
        input.value = String(str);
        document.body.appendChild(input);
        input.select();
        try {
            let success = document.execCommand("copy"),
            msg = success ? "复制成功!" : "复制失败!";
            Toast(msg);
        } catch (e) {
            Toast("浏览器暂不支持复制")
        }
        document.body.removeChild(input);
    } else {
        //Toast("内容为空")
    }
}
